// Runs a view page from what its module says of it. The sections and
// fields are in the page's HTML, each value's place marked data-field;
// this module reads the record into them, hides a field while its
// condition holds, and offers the page's actions, each a link to another
// page or an operation run on the record once the person confirms it.
// Every view page uses it.

import { on, emit } from "./events.js";
import { arrived, go, href, parameters } from "./pages.js";
import { ask } from "./ask.js";
import { call, save } from "./service.js";

// What holds values: the record, a value with parts and an item of a list.
const HOLDERS = "#record, [data-field], [data-item]";

/** The places under a holder that are its own, not a holder's within it. */
function own(holder) {
  return [...holder.querySelectorAll("[data-field]")].filter((place) => place.parentElement.closest(HOLDERS) === holder);
}

/** Puts a record's values into a holder's places: a value with parts into
    its parts, a list as one item per entry. */
function fill(holder, record) {
  for (const place of own(holder)) {
    const value = record?.[place.dataset.field];
    if (place.dataset.list !== undefined) {
      const items = place.querySelector(":scope > ul");
      const template = place.querySelector(":scope > template");
      items.replaceChildren();
      for (const entry of value ?? []) {
        const item = template.content.firstElementChild.cloneNode(true);
        if (own(item).length > 0) {
          fill(item, entry);
        } else {
          item.textContent = String(entry ?? "");
        }
        items.append(item);
      }
    } else if (own(place).length > 0) {
      fill(place, value);
    } else {
      place.textContent = String(value ?? "");
    }
  }
}

/** Fills the view, reads its record and runs its actions. */
export function view(page) {
  const given = parameters();
  const record = document.getElementById("record");
  const bar = document.getElementById("actions");
  const line = document.getElementById("status");
  let current;

  function refusal(operation, status) {
    return page.refusals[operation][String(status)] ?? page.messages.failed;
  }

  function show(text, failed) {
    line.textContent = text;
    line.classList.toggle("failed", failed);
  }

  async function load() {
    try {
      const response = await call(page.source, { parameters: given });
      if (!response.ok) {
        emit(page.failed, { status: response.status });
        return;
      }
      emit(page.loaded, { record: await response.json() });
    } catch {
      emit(page.failed, { status: 0 });
    }
  }

  async function run(action, button) {
    const reason = await ask(action.confirm, action.reason);
    if (reason === null) {
      return;
    }
    const sent = { parameters: action.parameters(current) };
    if (action.reason) {
      sent.body = { [action.reason.name]: reason };
    }
    button.disabled = true;
    try {
      const response = await call(action, sent);
      button.disabled = false;
      if (response.ok) {
        if (action.stream === "download") {
          await save(response, action.operation);
        }
        emit(action.succeeded, { id: current[page.key] });
      } else {
        emit(action.failed, { id: current[page.key], status: response.status });
      }
    } catch {
      button.disabled = false;
      emit(action.failed, { id: current[page.key], status: 0 });
    }
  }

  on(page.loaded, (payload) => {
    current = payload.record;
    fill(record, current);
    for (const [name, rule] of Object.entries(page.hidden)) {
      own(record).find((place) => place.dataset.field === name).parentElement.hidden = rule(current);
    }
    bar.replaceChildren();
    for (const action of page.actions) {
      if (action.when && !action.when(current)) {
        continue;
      }
      if (action.page) {
        const link = document.createElement("a");
        link.href = href(action.page, action.with(current, given));
        link.textContent = action.label;
        bar.append(link);
        continue;
      }
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = action.label;
      button.addEventListener("click", () => run(action, button));
      bar.append(button);
    }
  });
  on(page.failed, ({ status }) => show(refusal(page.source.operation, status), true));
  for (const action of page.actions.filter((action) => action.operation)) {
    on(action.succeeded, () => {
      if (action.signIn) {
        // identity-provider.js is written when the specification declares signIn.
        import("./identity-provider.js").then(({ signIn }) => signIn()).catch((error) => show(error.message, true));
        return;
      }
      if (action.navigate) {
        go(action.navigate.page, action.navigate.with(current, given), action.message);
        return;
      }
      show(action.message, false);
      load();
    });
    on(action.failed, ({ status }) => show(refusal(action.operation, status), true));
  }
  show(arrived(), false);
  load();
}
